package com.hrms.department.controller;
import com.hrms.auth.security.AuthPrincipal;import com.hrms.common.responses.*;import com.hrms.department.dto.*;import com.hrms.department.model.DepartmentStatus;import com.hrms.department.repository.*;import com.hrms.department.service.DepartmentService;import io.swagger.v3.oas.annotations.*;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.validation.Valid;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin/departments") @Tag(name="Departments") @SecurityRequirement(name="bearerAuth") @PreAuthorize("hasRole('ADMIN')")
public class DepartmentController {private final DepartmentService service;private final ClockSource clock;public DepartmentController(DepartmentService s,ClockSource c){service=s;clock=c;}
 @PostMapping public ApiResponse<DepartmentResponse> create(@Valid @RequestBody CreateDepartmentRequest r,@AuthenticationPrincipal AuthPrincipal a){return ApiResponse.success("Department created",service.create(r,a),clock);}
 @GetMapping public ApiResponse<DepartmentPageResponse> list(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int limit,@RequestParam(required=false)String search,@RequestParam(required=false)DepartmentStatus status,@RequestParam(defaultValue="createdAt")String sortBy,@RequestParam(defaultValue="desc")String sortDirection){return ApiResponse.success("Departments retrieved",service.list(new DepartmentSearch(search,status,page,limit,sortBy,sortDirection)),clock);}
 @GetMapping("/{id}") public ApiResponse<DepartmentResponse> get(@PathVariable String id){return ApiResponse.success("Department retrieved",service.get(id),clock);}
 @PatchMapping("/{id}") public ApiResponse<DepartmentResponse> update(@PathVariable String id,@Valid @RequestBody UpdateDepartmentRequest r,@AuthenticationPrincipal AuthPrincipal a){return ApiResponse.success("Department updated",service.update(id,r,a),clock);}
 @PatchMapping("/{id}/deactivate") public ApiResponse<DepartmentResponse> deactivate(@PathVariable String id,@AuthenticationPrincipal AuthPrincipal a){return ApiResponse.success("Department deactivated",service.deactivate(id,a),clock);}
 @PatchMapping("/{id}/reactivate") public ApiResponse<DepartmentResponse> reactivate(@PathVariable String id,@AuthenticationPrincipal AuthPrincipal a){return ApiResponse.success("Department reactivated",service.reactivate(id,a),clock);}}
